#!/bin/bash
#
###############################################################################
# Script to configure and enable Mirroring 
# maintainer: 
# 
#
# USAGE
#   - Copy script files to ASIK (for example to /ffs/run/config/scripts/ folder)
#       - 
#   - Give execution rights 
#       chmod +x /ffs/run/config/scripts/*.sh
#   - Modify options in gnbMirroringConfig.sh
#   - Run script
#       sh /ffs/run/config/scripts/
#   - capture is stored to /tmp/tcpdump_L2L1_bip[_filtering_[off|on].pcap000
#   - Remember to delete captures from ASIB after downloading to not to break SW upgrade due to insufficient disk space
#

VERSION_STRING='V02'

YELLOW='\e[33m'
RED='\e[31m'
GREEN='\e[32m'
NC='\e[0m'

directory="$( cd "$( dirname "${BASH_SOURCE[0]}" )" >/dev/null 2>&1 && pwd )"


readOptionsFromConfigFile() {
    source $directory/gnbMirroringConfig.sh
    if [ $? -eq 0 ]; then 
        echo -e "\n${YELLOW}Read options from gnbMirroringConfig.sh${NC}"
    else 
        echo -e "\n${RED}Config file (gnbMirroringConfig.sh) not found${NC}"
        exit
    fi
}

readOptionsFromComonFile() {
    source $directory/common_funcs.sh
    if [ $? -eq 0 ]; then 
        echo -e "\n${YELLOW}Read options from common_funcs.sh${NC}"
    else 
        echo -e "\n${RED}Config file (common_funcs.sh) not found${NC}"
        exit
    fi
}


echo -e "\n${YELLOW}bip_asbi_abio.sh $VERSION_STRING${NC}"
readOptionsFromConfigFile
readOptionsFromComonFile
parseCommandLineOptions "$@"

if [ $XTRACE = 'on' ]; then
    set -x
fi

if [ ! $controlCardHwType ]; then
    checkSwReleaseAndHW
fi

slot_array=(1 2 3 5 6 7)
declare -A controlboard_eth_dict
declare -A controlboard_port_dict

controlboard_eth_dict=([ASIB]="ethsei02" [ASIL]="sei11")
controlboard_port_dict=([ASIB]=2 [ASIL]=6)
vlan_server_id=303
vlan_server_list=()
for i in ${slot_array[@]}
do
	slot_id=${i}
	eval bb_slot_tmp='$'BB_SLOT_${slot_id}
	if [ "$bb_slot_tmp" == "false" ]; then
	continue
	fi

	if [ ${slot_id} -lt 4 ]; then
		fcp_id=1
		fsp_id=$slot_id
	else
		fcp_id=2
		fsp_id=$(($slot_id-1))
	fi

    core_id="C${fcp_id}B${fsp_id}"
    echo "${core_id}(2)"
    echo "BB_SLOT_${slot_id} is true."
    destion_eth=${controlboard_eth_dict[${controlCardHwType}]}
    destion_port=${controlboard_port_dict[${controlCardHwType}]}

    if [ "${L2_L1_BIP}" = "true" ];then
    /usr/bin/lfs-nw_switch-mirror-tool.sh -p 0 -d ${destion_eth} -f L1_L2_UL -b "C${fcp_id}B${fsp_id}(${destion_port})" -s $slot_id -l eths3 -v $vlan_server_id
    vlan_server_list[${#vlan_server_list[*]}]=${vlan_server_id}
    sleep 1
    vlan_server_id=$((${vlan_server_id}+1))
    /usr/bin/lfs-nw_switch-mirror-tool.sh -p 0 -d ${destion_eth} -f L1_L2_DL -b "C${fcp_id}B${fsp_id}(${destion_port})" -s $slot_id -l eths3 -v $vlan_server_id
    vlan_server_list[${#vlan_server_list[*]}]=${vlan_server_id}
    sleep 1
    vlan_server_id=$((${vlan_server_id}+1))
	fi

    if [ "${L2HI_L2RT}" = "true" ];then
    /usr/bin/lfs-nw_switch-mirror-tool.sh -p 0 -d ${destion_eth} -f L2HI_L2RT -b "C${fcp_id}B${fsp_id}(${destion_port})" -s $slot_id -l eths3 -v $vlan_server_id
    vlan_server_list[${#vlan_server_list[*]}]=${vlan_server_id}
    sleep 1
    vlan_server_id=$((${vlan_server_id}+1))
	fi

    #L2HI_TRSW traffic
    if [ "$controlCardHwType" = "ASIB" ]; then
        if [ $slot_id -eq 1 ] || [ $slot_id -eq 5 ]; then
            port1=5
            port2=6	
        elif [ $slot_id -eq 2 ] || [ $slot_id -eq 6 ]; then
            port1=9
            port2=10	
        elif [ $slot_id -eq 3 ] || [ $slot_id -eq 7 ]; then
            port1=13
            port2=14	
        fi
        echo 3 both > /var/run/cpss/ports/$port1/mirroring_port 
        echo 3 both > /var/run/cpss/ports/$port2/mirroring_port
    fi
done


if [ "$controlCardHwType" = "ASIB" ]; then
    echo "**********Mirroring to $controlCardHwType netdriver"
    ncp_portmirror -p xgmac96 -r
    ncp_portmirror -d netdriver -p xgmac96
    ncp_l2 -p XGMAC96 -I -senableSwitching.false
    ncp_l2 -p XGMAC96 -i -sdiscardInvalidVlanidPackets.false
    ncp_l2 -p XGMAC96 -i -sdiscardBadLengthPackets.false
elif [ "$controlCardHwType" = "ASIL" ]; then
    echo "**********Mirroring to $controlCardHwType netdriver"
    #Close ASIL MAC learning
    bcicmd -n 3msd -c "/dbg3ms/port 36 set learning 0 0 1"
    echo 'vlan server list is: '${vlan_server_list[*]}
    #ASIL config vlan to port 13
    for j in ${vlan_server_list[@]}
    do
        bcicmd -n 3msd -c "/dbg3ms/vlan add ${j} 13 untagged"
        bcicmd -n 3msd -c "/dbg3ms/vlan remove ${j} 21"
    done
        dbgnac set port 2 speed 25000
        dbgnac enable port 2
        dbgnac set port 2 loop e t
        dbgnac mirror sport 0 dport 2 e b
        dbgnac mirror sport 2 dport 20 e b
        /usr/bin/netd_uspace_lnk 2 1 25000 1
        ifconfig nac_eth2 up
        ifconfig nac_eth2 promisc
fi


echo "**********Dump file will be stored in /tmp/"
evaluateTimeout
rm /tmp/tcpdump_L2L1_bip*

if [ "$controlCardHwType" = "ASIL" ] && [ "$L1bypass" = "FS" ]; then
    eval $timeoutCommand "tcpdump -i any -C $FILE_SIZE_MBYTES -W $NUMBER_OF_FILES -vvv -w /tmp/tcpdump_L2L1_bip_filtering_$FILTERING.pcap '$filtered_messages'"
elif [ "$controlCardHwType" = "ASIL" ] && [ "$L1bypass" != "FS" ]; then
  eval $timeoutCommand "tcpdump -i nac_eth2 -C $FILE_SIZE_MBYTES -W $NUMBER_OF_FILES -vvv -w /tmp/tcpdump_L2L1_bip_filtering_$FILTERING.pcap '$filtered_messages'"
else
    eval $timeoutCommand "tcpdump -i eths3 -C $FILE_SIZE_MBYTES -W $NUMBER_OF_FILES -vvv -w /tmp/tcpdump_L2L1_bip_filtering_$FILTERING.pcap '$filtered_messages'"
fi